/*
 * Built for Kinetic from scratch after the public preview of BoardUI's "Line Chart Card" (boardui.com/components/line-chart-card).
 * No BoardUI source was used.
 */
"use client";

import { Fragment, useId, useState } from "react";
import { Area, CartesianGrid, ComposedChart, Line, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";

import { useReducedMotion } from "@/hooks/use-reduced-motion";
import { cx } from "@/lib/cx";
import {
  AXIS_TICK,
  CHART_CARD_FRAME,
  CHART_CURSOR,
  ChartHeadline,
  ChartLegend,
  ChartPeriodControl,
  ChartTooltipCard,
  GRID_STROKE,
  PulseDot,
  describeDelta,
  formatCompact,
  formatNumber,
  toneActiveColor,
  toneColor,
} from "@/components/motion/line-chart-card-parts";
import type { ChartTone } from "@/components/motion/line-chart-card-parts";

/**
 * Line Chart Card: one or more series drawn as smooth lines over a dashed
 * horizontal grid, in the kit's grey card shell. The headline is the latest
 * value of the first series with its change against the point before; the
 * period switch swaps the whole data set (week, month or year buckets).
 * Hovering draws a dashed cursor, a pinging dot on every line and a tooltip
 * card listing each series, and the headline counts to the hovered point.
 */

export type LineSeries = {
  /** Field on each point that holds this series' value. */
  key: string;
  label: string;
  /** Theme hue, `chart-1` … `chart-9`. */
  tone: ChartTone;
  /** Fill the area under the line with a fading gradient. */
  area?: boolean;
};

/** One x position: its axis label plus a number per series key. */
export type LinePoint = { label: string } & Record<string, string | number>;

export type LinePeriod = { id: string; label: string; data: LinePoint[] };

export const LINE_SERIES: LineSeries[] = [
  { key: "revenue", label: "Revenue", tone: 2, area: true },
  { key: "costs", label: "Costs", tone: 6 },
];

const WEEKS = ["Aug 4", "Aug 11", "Aug 18", "Aug 25", "Sep 1", "Sep 8", "Sep 15", "Sep 22", "Sep 29", "Oct 6", "Oct 13", "Oct 20"];
const MONTHS = ["Nov", "Dec", "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct"];
const YEARS = ["2018", "2019", "2020", "2021", "2022", "2023", "2024", "2025"];

const zip = (labels: string[], revenue: number[], costs: number[]): LinePoint[] =>
  labels.map((label, i) => ({ label, revenue: revenue[i] ?? 0, costs: costs[i] ?? 0 }));

/** Week, month and year buckets of the same business; each ends on its latest bucket. */
export const LINE_PERIODS: LinePeriod[] = [
  {
    id: "weekly",
    label: "Weekly",
    data: zip(
      WEEKS,
      [12480, 13120, 12760, 14010, 14630, 13980, 15240, 15870, 15310, 16420, 16670, 18240],
      [8120, 8340, 8410, 8760, 9020, 8890, 9310, 9580, 9440, 9870, 10120, 10460],
    ),
  },
  {
    id: "monthly",
    label: "Monthly",
    data: zip(
      MONTHS,
      [48200, 52900, 46100, 49800, 55300, 54100, 58600, 61200, 59400, 63800, 66100, 71450],
      [33100, 35800, 32400, 33900, 36200, 35800, 37900, 39100, 38600, 40200, 41300, 43700],
    ),
  },
  {
    id: "yearly",
    label: "Yearly",
    data: zip(
      YEARS,
      [312000, 358000, 401000, 447000, 523000, 588000, 642000, 731000],
      [228000, 251000, 276000, 301000, 342000, 371000, 398000, 442000],
    ),
  },
];

const valueAt = (point: LinePoint | undefined, key: string) => {
  const raw = point?.[key];
  return typeof raw === "number" ? raw : Number(raw ?? 0);
};

export type LineChartCardProps = {
  title?: string;
  /** Series in legend order; the first one drives the headline and is drawn on top. */
  series?: LineSeries[];
  periods?: LinePeriod[];
  /** Controlled period id. */
  period?: string;
  /** Initial period when uncontrolled; defaults to the first period. */
  defaultPeriod?: string;
  onPeriodChange?: (id: string) => void;
  /** `curved` is a monotone spline; `sharp` joins the points with straight segments. */
  shape?: "curved" | "sharp";
  /** Header switch style. */
  periodControl?: "segmented" | "select";
  /** Prepended to every value ("$"). */
  valuePrefix?: string;
  className?: string;
};

// #region critical
export function LineChartCard({
  title = "Revenue",
  series = LINE_SERIES,
  periods = LINE_PERIODS,
  period,
  defaultPeriod,
  onPeriodChange,
  shape = "curved",
  periodControl = "segmented",
  valuePrefix = "$",
  className,
}: LineChartCardProps = {}) {
  const reduced = useReducedMotion();
  const gradientBase = useId();
  const [innerPeriod, setInnerPeriod] = useState(defaultPeriod ?? periods[0]?.id ?? "");
  const periodId = period ?? innerPeriod;
  const active = periods.find((p) => p.id === periodId) ?? periods[0];
  const data = active?.data ?? [];
  const [hovered, setHovered] = useState<number | null>(null);

  const primary = series[0];
  const index = hovered !== null && hovered < data.length ? hovered : data.length - 1;
  const point = data[index];
  const headline = primary ? valueAt(point, primary.key) : 0;
  const before = index > 0 && primary ? valueAt(data[index - 1], primary.key) : undefined;
  const money = (n: number) => `${valuePrefix}${formatNumber(n)}`;
  const curve = shape === "sharp" ? "linear" : "monotone";

  const selectPeriod = (id: string) => {
    setHovered(null);
    if (period === undefined) setInnerPeriod(id);
    onPeriodChange?.(id);
  };

  return (
    <section aria-label={`${title} chart`} className={cx(CHART_CARD_FRAME, "h-[376px]", className)}>
      <div className="flex flex-col gap-3 px-2 pt-2 @md:flex-row @md:items-start @md:justify-between">
        <ChartHeadline
          label={hovered !== null && point ? `${title} · ${point.label}` : title}
          value={headline}
          format={money}
          delta={describeDelta(headline, before)}
          swapKey={`${periodId}-${hovered ?? "latest"}`}
          reducedMotion={reduced}
        />
        <div className="flex flex-col gap-2 @md:items-end">
          {periods.length > 1 ? (
            <ChartPeriodControl
              options={periods}
              value={periodId}
              onChange={selectPeriod}
              variant={periodControl}
              label={`${title} period`}
              className="self-start @md:self-end"
            />
          ) : null}
          {series.length > 1 ? <ChartLegend items={series} className="@md:pe-1" /> : null}
        </div>
      </div>

      <div className="min-h-0 w-full flex-1 pt-3 pe-2">
        <ResponsiveContainer width="100%" height="100%" initialDimension={{ width: 520, height: 240 }}>
          <ComposedChart
            data={data}
            margin={{ top: 8, right: 8, bottom: 0, left: 0 }}
            onMouseMove={(state) => {
              const next = Number(state?.activeTooltipIndex);
              if (state?.isTooltipActive && Number.isFinite(next)) setHovered(next);
            }}
            onMouseLeave={() => setHovered(null)}
          >
            <defs>
              {series.map((s) =>
                s.area ? (
                  <linearGradient key={s.key} id={`${gradientBase}-${s.key}`} x1="0" y1="0" x2="0" y2="1">
                    <stop offset="0%" stopColor={toneColor(s.tone)} stopOpacity={0.4} />
                    <stop offset="100%" stopColor={toneColor(s.tone)} stopOpacity={0} />
                  </linearGradient>
                ) : null,
              )}
            </defs>
            <CartesianGrid vertical={false} stroke={GRID_STROKE} strokeDasharray="4 4" />
            <YAxis
              width={48}
              domain={[0, "auto"]}
              tickCount={4}
              tickFormatter={(v: number) => formatCompact(v, valuePrefix)}
              tickLine={false}
              axisLine={false}
              tick={AXIS_TICK}
            />
            <XAxis
              dataKey="label"
              tickLine={false}
              axisLine={false}
              tickMargin={10}
              interval="preserveStartEnd"
              minTickGap={12}
              tick={AXIS_TICK}
            />
            <Tooltip
              cursor={CHART_CURSOR}
              offset={16}
              isAnimationActive={!reduced}
              animationDuration={160}
              wrapperStyle={{ outline: "none", zIndex: 10 }}
              content={({ active: isActive, activeIndex }) => {
                const at = data[activeIndex == null ? -1 : Number(activeIndex)];
                if (!isActive || !at) return null;
                return (
                  <ChartTooltipCard
                    title={at.label}
                    rows={series.map((s) => ({ key: s.key, label: s.label, tone: s.tone, value: money(valueAt(at, s.key)) }))}
                  />
                );
              }}
            />
            {/* Paint in reverse so the first (headline) series sits on top. */}
            {[...series].reverse().map((s) => (
              <Fragment key={s.key}>
                {s.area ? (
                  <Area
                    type={curve}
                    dataKey={s.key}
                    name={s.label}
                    stroke="none"
                    fill={`url(#${gradientBase}-${s.key})`}
                    activeDot={false}
                    isAnimationActive={!reduced}
                    animationDuration={450}
                  />
                ) : null}
                <Line
                  type={curve}
                  dataKey={s.key}
                  name={s.label}
                  stroke={toneActiveColor(s.tone)}
                  strokeWidth={2.5}
                  dot={false}
                  activeDot={<PulseDot color={toneActiveColor(s.tone)} pulse={!reduced} />}
                  isAnimationActive={!reduced}
                  animationDuration={450}
                />
              </Fragment>
            ))}
          </ComposedChart>
        </ResponsiveContainer>
      </div>
    </section>
  );
}
// #endregion

/*
 * Built for Kinetic from scratch after the public preview of BoardUI's "Line Chart Card" (boardui.com/components/line-chart-card).
 * No BoardUI source was used.
 */
"use client";

import type { ReactNode } from "react";
import { RiCalendarLine } from "@remixicon/react";

import { Chip } from "@/components/motion/chip";
import type { ChipColor } from "@/components/motion/chip";
import { SegmentedControl, SegmentedControlItem } from "@/components/motion/segmented-control";
import { Select, SelectItem } from "@/components/motion/select";
import { useCountUp } from "@/hooks/use-count-up";
import { cx } from "@/lib/cx";

/**
 * Shared pieces of the BoardUI-kit chart cards: the card frame, the count-up
 * headline with its delta chip, the period switch (segmented or a calendar
 * pill), the floating tooltip card, legend dots and the stat tiles that sit
 * under a chart. Colours are the theme's `chart-N` tokens throughout, so a
 * card follows light and dark mode with no per-theme code.
 */

/** One of the nine categorical hues in the kit theme (`--color-chart-N`). */
export type ChartTone = 1 | 2 | 3 | 4 | 5 | 6 | 7 | 8 | 9;

/** Base fill of a tone, for areas, bars and polygons. */
export const toneColor = (tone: ChartTone) => `var(--color-chart-${tone})`;
/** The darker `-active` step of a tone, for strokes and hovered marks. */
export const toneActiveColor = (tone: ChartTone) => `var(--color-chart-${tone}-active)`;

/** Static class map, so Tailwind sees every dot colour at build time. */
export const TONE_DOT: Record<ChartTone, string> = {
  1: "bg-chart-1-active",
  2: "bg-chart-2-active",
  3: "bg-chart-3-active",
  4: "bg-chart-4-active",
  5: "bg-chart-5-active",
  6: "bg-chart-6-active",
  7: "bg-chart-7-active",
  8: "bg-chart-8-active",
  9: "bg-chart-9-active",
};

/** The card surface every chart card shares. `@container` lets tiles reflow by card width. */
export const CHART_CARD_FRAME =
  "@container flex min-w-0 flex-col rounded-2xl bg-background-secondary-default p-2";

/** Axis tick style: 12px tertiary text, readable in both themes. */
export const AXIS_TICK = { fontSize: 12, fill: "var(--color-text-tertiary)" } as const;

/** Vertical hover cursor drawn by `<Tooltip cursor>`. */
export const CHART_CURSOR = {
  stroke: "var(--color-chart-cursor)",
  strokeWidth: 1,
  strokeDasharray: "4 4",
} as const;

/** Dashed horizontal grid line colour. */
export const GRID_STROKE = "var(--color-chart-track)";

const trimDecimal = (value: number) => String(Math.round(value * 10) / 10);

/** 13500 → "13.5K", 6000 with "$" → "$6K", 1.2e6 → "1.2M". */
export function formatCompact(value: number, prefix = "", suffix = "") {
  const abs = Math.abs(value);
  if (abs >= 1_000_000) return `${prefix}${trimDecimal(value / 1_000_000)}M${suffix}`;
  if (abs >= 1000) return `${prefix}${trimDecimal(value / 1000)}K${suffix}`;
  return `${prefix}${trimDecimal(value)}${suffix}`;
}

/** Grouped en-US number with a fixed number of decimals. */
export function formatNumber(value: number, decimals = 0) {
  return value.toLocaleString("en-US", {
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals,
  });
}

export type ChartDelta = { label: string; color: ChipColor };

/** Percentage change as a chip: "+9.4%" lime, "-3.1%" rose, "0%" neutral, "New" with no baseline. */
export function describeDelta(current: number, previous: number | undefined): ChartDelta {
  if (previous === undefined || previous === 0) return { label: "New", color: "neutral" };
  const change = Math.round(((current - previous) / Math.abs(previous)) * 1000) / 10;
  if (change === 0) return { label: "0%", color: "neutral" };
  return { label: `${change > 0 ? "+" : ""}${change}%`, color: change > 0 ? "lime" : "rose" };
}

export function ChartHeadline({
  label,
  value,
  format = (n) => formatNumber(n),
  decimals = 0,
  delta,
  swapKey,
  reducedMotion = false,
}: {
  /** Small secondary line above the figure. */
  label: ReactNode;
  /** Target figure; the display counts to it whenever it changes. */
  value: number;
  /** Turns the counted number into text ("$18,240"). */
  format?: (value: number) => string;
  /** Decimals kept while counting (the hook itself counts in integers). */
  decimals?: number;
  delta?: ChartDelta | null;
  /** Changing this replays the soft number fade, e.g. the hovered index. */
  swapKey?: string | number;
  /** Skip the count and the fade. */
  reducedMotion?: boolean;
}) {
  const scale = 10 ** decimals;
  const target = Math.round(value * scale);
  const counted = useCountUp(target);
  const shown = (reducedMotion ? target : counted) / scale;
  return (
    <div className="flex min-w-0 flex-col gap-0.5">
      <p className="truncate text-body-medium text-text-secondary">{label}</p>
      <div className="flex min-w-0 items-center gap-2">
        <p
          key={swapKey}
          className="animate-number-fade text-title-1-medium whitespace-nowrap text-text-primary tabular-nums motion-reduce:animate-none"
        >
          {format(shown)}
        </p>
        {delta ? (
          <Chip variant="bold" color={delta.color} className="tabular-nums">
            {delta.label}
          </Chip>
        ) : null}
      </div>
    </div>
  );
}

export type ChartPeriod = { id: string; label: string };

/**
 * The period switch in a card header: a segmented Weekly / Monthly / Yearly
 * control, or a bordered pill with a calendar glyph that opens a listbox.
 */
export function ChartPeriodControl({
  options,
  value,
  onChange,
  variant = "segmented",
  label = "Period",
  className,
}: {
  options: readonly ChartPeriod[];
  value: string;
  onChange: (id: string) => void;
  variant?: "segmented" | "select";
  /** Accessible name of the control. */
  label?: string;
  className?: string;
}) {
  if (variant === "select") {
    return (
      <Select
        aria-label={label}
        size="sm"
        selectedKey={value}
        onSelectionChange={(key) => {
          if (key !== null) onChange(String(key));
        }}
        className={className}
        triggerClassName="gap-1.5 py-1.5 ps-2.5 pe-2 text-body-medium"
        popoverClassName="w-44"
        renderValue={({ selectedText }) => (
          <>
            <RiCalendarLine aria-hidden className="size-4 shrink-0 text-text-secondary" />
            <span className="truncate">{selectedText}</span>
          </>
        )}
      >
        {options.map((option) => (
          <SelectItem key={option.id} id={option.id} textValue={option.label}>
            {option.label}
          </SelectItem>
        ))}
      </Select>
    );
  }
  return (
    <SegmentedControl
      aria-label={label}
      selectedKeys={[value]}
      onSelectionChange={(keys) => {
        const next = [...keys][0];
        if (next !== undefined) onChange(String(next));
      }}
      className={className}
    >
      {options.map((option) => (
        <SegmentedControlItem key={option.id} id={option.id}>
          {option.label}
        </SegmentedControlItem>
      ))}
    </SegmentedControl>
  );
}

export type ChartTooltipRow = {
  key: string;
  label: ReactNode;
  value: ReactNode;
  tone?: ChartTone;
};

/** The floating card a chart's `<Tooltip content>` renders: a title and one row per series. */
export function ChartTooltipCard({ title, rows }: { title: ReactNode; rows: readonly ChartTooltipRow[] }) {
  return (
    <div className="min-w-40 rounded-xl border border-border-button-default bg-background-primary-default px-3 py-2.5 shadow-dropdown">
      <p className="text-caption-1-medium text-text-tertiary">{title}</p>
      <ul className="mt-1.5 flex flex-col gap-1">
        {rows.map((row) => (
          <li key={row.key} className="flex items-center gap-2 text-body-2-regular text-text-secondary">
            {row.tone ? <span aria-hidden className={cx("size-2 shrink-0 rounded-full", TONE_DOT[row.tone])} /> : null}
            <span className="min-w-0 flex-1 truncate">{row.label}</span>
            <span className="ms-4 text-body-2-medium text-text-primary tabular-nums">{row.value}</span>
          </li>
        ))}
      </ul>
    </div>
  );
}

export type ChartLegendItem = { key: string; label: ReactNode; tone: ChartTone };

/** A row of round colour dots naming each series. */
export function ChartLegend({ items, className }: { items: readonly ChartLegendItem[]; className?: string }) {
  return (
    <ul className={cx("flex flex-wrap items-center gap-x-4 gap-y-1 text-body-2-medium text-text-secondary", className)}>
      {items.map((item) => (
        <li key={item.key} className="flex items-center gap-1.5">
          <span aria-hidden className={cx("size-2 rounded-full", TONE_DOT[item.tone])} />
          {item.label}
        </li>
      ))}
    </ul>
  );
}

export type ChartStatTile = {
  key: string;
  label: ReactNode;
  value: ReactNode;
  /** Square colour key before the label; omit for plain tiles. */
  tone?: ChartTone;
};

const TILE_COLUMNS = {
  2: "grid-cols-2",
  3: "grid-cols-3",
  "3-wrap": "grid-cols-2 @sm:grid-cols-3",
} as const;

/** White tiles under a chart, one per series or category. */
export function ChartStatTiles({
  tiles,
  columns = 3,
  className,
}: {
  tiles: readonly ChartStatTile[];
  /** 2 or 3 fixed columns, or "3-wrap": two columns until the card is 384px wide. */
  columns?: keyof typeof TILE_COLUMNS;
  className?: string;
}) {
  return (
    <dl className={cx("grid gap-2", TILE_COLUMNS[columns], className)}>
      {tiles.map((tile) => (
        <div key={tile.key} className="flex min-w-0 flex-col gap-0.5 rounded-xl bg-background-primary-default px-2.5 py-2">
          <dt className="flex min-w-0 items-center gap-1.5 text-body-medium text-text-secondary">
            {tile.tone ? (
              <span aria-hidden className={cx("size-2.5 shrink-0 rounded-[3px]", TONE_DOT[tile.tone])} />
            ) : null}
            <span className="truncate">{tile.label}</span>
          </dt>
          <dd className="truncate text-body-medium text-text-primary tabular-nums">{tile.value}</dd>
        </div>
      ))}
    </dl>
  );
}

/**
 * The marker on a hovered point: a solid dot ringed in the card colour, with a
 * soft ping behind it unless motion is reduced. Recharts clones it with cx/cy.
 */
export function PulseDot({
  cx: x,
  cy: y,
  color,
  pulse = true,
}: {
  cx?: number;
  cy?: number;
  color: string;
  pulse?: boolean;
}) {
  if (x === undefined || y === undefined) return null;
  return (
    <g pointerEvents="none">
      {pulse ? (
        <circle
          cx={x}
          cy={y}
          r={6}
          fill={color}
          opacity={0.35}
          className="origin-center animate-ping [transform-box:fill-box] motion-reduce:animate-none"
        />
      ) : null}
      <circle cx={x} cy={y} r={4.5} fill={color} stroke="var(--color-background-secondary-default)" strokeWidth={2} />
    </g>
  );
}
